//! markitai: glyph name lookup by binary search.
//!
//! `sorted_names.rs`, generated by `scripts/sorted_glyph_names.py` from the
//! glyph list in `glyph_names.rs` (`build_glyph_to_unicode_map` and the
//! overrides `GLYPH_TO_UNICODE` adds, both compiled only for tests), holds
//! every name with its character in byte order. At compile time the list is
//! checked to be strictly ascending and packed into one byte string with
//! 16-bit bounds, a parallel array of 16-bit code points and the range of
//! names each first byte starts, so nothing is built at run time and the
//! table holds no pointers for a position-independent executable to relocate
//! at load. A search covers one first byte's range: about 7 steps on
//! average instead of 12.

use core::cmp::Ordering;

use super::sorted_names::SORTED_GLYPH_NAMES as NAMES;

const COUNT: usize = NAMES.len();

/// The length of all names together.
const NAME_BYTES_LEN: usize = {
    let mut total = 0;
    let mut i = 0;
    while i < COUNT {
        total += NAMES[i].0.len();
        i += 1;
    }
    total
};

// `NAME_BOUNDS` holds 16-bit offsets.
const _: () = assert!(NAME_BYTES_LEN <= u16::MAX as usize);

// Binary search needs strictly ascending names, which also rules out a name
// listed twice.
const _: () = {
    let mut i = 1;
    while i < COUNT {
        assert!(
            precedes(NAMES[i - 1].0.as_bytes(), NAMES[i].0.as_bytes()),
            "glyph names out of order; run scripts/sorted_glyph_names.py"
        );
        i += 1;
    }
};

/// Every name, concatenated in table order.
static NAME_BYTES: [u8; NAME_BYTES_LEN] = {
    let mut bytes = [0; NAME_BYTES_LEN];
    let mut at = 0;
    let mut i = 0;
    while i < COUNT {
        let name = NAMES[i].0.as_bytes();
        let mut j = 0;
        while j < name.len() {
            bytes[at] = name[j];
            at += 1;
            j += 1;
        }
        i += 1;
    }
    bytes
};

/// Name `i` is `NAME_BYTES[NAME_BOUNDS[i]..NAME_BOUNDS[i + 1]]`.
static NAME_BOUNDS: [u16; COUNT + 1] = {
    let mut bounds = [0; COUNT + 1];
    let mut i = 0;
    while i < COUNT {
        bounds[i + 1] = bounds[i] + NAMES[i].0.len() as u16;
        i += 1;
    }
    bounds
};

/// The code point of name `i`'s character. Every character is in the Basic
/// Multilingual Plane, and none is a surrogate since it is a `char`.
static CODES: [u16; COUNT] = {
    let mut codes = [0; COUNT];
    let mut i = 0;
    while i < COUNT {
        let code = NAMES[i].1 as u32;
        assert!(
            code <= u16::MAX as u32,
            "glyph character outside the Basic Multilingual Plane"
        );
        codes[i] = code as u16;
        i += 1;
    }
    codes
};

/// The names starting with byte `b` are those from `FIRST[b]` up to
/// `FIRST[b + 1]`, since the names are in byte order.
static FIRST: [u16; 257] = {
    let mut first = [0; 257];
    let mut i = 0;
    while i < COUNT {
        let name = NAMES[i].0.as_bytes();
        assert!(!name.is_empty(), "empty glyph name");
        first[name[0] as usize + 1] += 1;
        i += 1;
    }
    let mut byte = 0;
    while byte < 256 {
        first[byte + 1] += first[byte];
        byte += 1;
    }
    first
};

/// Whether `a` sorts strictly before `b`, comparing bytes.
const fn precedes(a: &[u8], b: &[u8]) -> bool {
    let mut i = 0;
    while i < a.len() && i < b.len() {
        if a[i] != b[i] {
            return a[i] < b[i];
        }
        i += 1;
    }
    a.len() < b.len()
}

/// The character of the glyph named `name`, if the list has that name.
pub(super) fn char_of(name: &[u8]) -> Option<char> {
    let first = usize::from(*name.first()?);
    let mut low = usize::from(FIRST[first]);
    let mut high = usize::from(FIRST[first + 1]);
    while low < high {
        let mid = low + (high - low) / 2;
        let candidate = &NAME_BYTES[NAME_BOUNDS[mid] as usize..NAME_BOUNDS[mid + 1] as usize];
        match candidate.cmp(name) {
            Ordering::Less => low = mid + 1,
            Ordering::Greater => high = mid,
            Ordering::Equal => return char::from_u32(u32::from(CODES[mid])),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::super::{glyph_name_to_string, glyph_to_char, glyph_to_unicode, GLYPH_TO_UNICODE};
    use super::*;

    /// What the replaced map lookup gave: the list's character for `name`,
    /// with the overrides applied.
    fn listed(name: &[u8]) -> Option<char> {
        let name = std::str::from_utf8(name).ok()?;
        GLYPH_TO_UNICODE.get(name).copied()
    }

    #[test]
    fn every_listed_name_has_its_character() {
        // With the names strictly ascending, an equal count and every listed
        // name found means the table holds exactly the listed names.
        assert_eq!(COUNT, GLYPH_TO_UNICODE.len());
        for (&name, &ch) in GLYPH_TO_UNICODE.iter() {
            assert_eq!(glyph_to_unicode(name), Some(ch), "{name}");
        }
    }

    /// Every prefix of each name, the name with a byte before or after it,
    /// with one byte changed by one, and with its letters' case flipped.
    #[test]
    fn changed_names_agree_with_the_listing() {
        let mut names: Vec<&str> = GLYPH_TO_UNICODE.keys().copied().collect();
        names.sort_unstable();
        let mut probes: Vec<Vec<u8>> = vec![
            Vec::new(),
            b"\xff".to_vec(),
            b"\0".to_vec(),
            b"zzzzzzzz".to_vec(),
        ];
        for name in names {
            let name = name.as_bytes();
            for end in 0..name.len() {
                probes.push(name[..end].to_vec());
            }
            for byte in [0, b'.', b'0', b'A', b'Z', b'_', b'a', b'z', 0x7f, 0xff] {
                probes.push([name, &[byte]].concat());
                probes.push([&[byte], name].concat());
            }
            for i in 0..name.len() {
                for delta in [1, u8::MAX] {
                    let mut changed = name.to_vec();
                    changed[i] = changed[i].wrapping_add(delta);
                    probes.push(changed);
                }
            }
            probes.push(
                name.iter()
                    .map(|byte| {
                        if byte.is_ascii_alphabetic() {
                            byte ^ 0x20
                        } else {
                            *byte
                        }
                    })
                    .collect(),
            );
        }
        let mut names = 0;
        for probe in &probes {
            let expected = listed(probe);
            names += usize::from(expected.is_some());
            assert_eq!(
                char_of(probe),
                expected,
                "{}",
                String::from_utf8_lossy(probe)
            );
            if let Ok(text) = std::str::from_utf8(probe) {
                assert_eq!(glyph_to_unicode(text), expected, "{text}");
            }
        }
        // Some changes give another name (`A` → `B`, `Acute` → `acute`); the
        // counts were also computed independently from the list.
        assert_eq!((probes.len(), names), (248_737, 9_055));
    }

    /// `glyph_to_char` reads every listed name, also with a suffix, and
    /// `glyph_name_to_string` every one but the five joined by underscores
    /// (`f_f_i`), which it reads by their components.
    #[test]
    fn the_name_readers_find_every_listed_name() {
        let mut joined = 0;
        for (&name, &ch) in GLYPH_TO_UNICODE.iter() {
            assert_eq!(glyph_to_char(name), Some(ch), "{name}");
            assert_eq!(glyph_to_char(&format!("{name}.alt")), Some(ch), "{name}");
            if name.contains('_') {
                joined += 1;
            } else {
                assert_eq!(glyph_name_to_string(name), Some(ch.to_string()), "{name}");
            }
        }
        assert_eq!(joined, 5);
    }

    #[test]
    fn known_names() {
        assert_eq!(glyph_to_unicode("A"), Some('A'));
        assert_eq!(glyph_to_unicode("AE"), Some('\u{00C6}'));
        assert_eq!(glyph_to_unicode("controlNULL"), Some('\0'));
        assert_eq!(glyph_to_unicode("zukatakana"), Some('\u{30BA}'));
        assert_eq!(glyph_to_unicode("a1"), Some('\u{2701}'));
        // The local overrides.
        assert_eq!(glyph_to_unicode("C21"), Some('\u{2265}'));
        assert_eq!(glyph_to_unicode("C24"), Some('~'));
        assert_eq!(glyph_to_unicode(""), None);
        assert_eq!(glyph_to_unicode("Space"), None);
        // Encoded names and suffixes are read by `glyph_to_char`, not here.
        assert_eq!(glyph_to_unicode("uni0041"), None);
        assert_eq!(glyph_to_unicode("a.sc"), None);
    }
}
